<x-layouts.app title="Settings"><x-page-header title="Settings" description="A familiar place to manage your account and workspace preferences." /><div class="content-grid"><div class="stack"><section class="card"><div class="card-heading"><h2>Profile settings</h2></div><div class="card-body"><p class="small muted leading-6 mb-5">View your current login account. Employee information and profile editing will be managed in a later phase.</p><x-button :href="route('profile')" variant="secondary">View your profile<x-icon name="arrow" /></x-button></div></section><section class="card"><div class="card-heading"><h2>Security</h2><x-badge>Session authentication</x-badge></div><div class="card-body"><p class="small muted leading-6 mb-5">You can securely end this browser session. Password recovery {{ Route::has('password.request') ? 'is configured.' : 'is unavailable until a private delivery channel is configured. Contact your administrator for help.' }}</p><x-button variant="secondary" @click="$dispatch('open-modal', 'logout')">Sign out of this session</x-button></div></section></div><div class="stack"><section class="card"><div class="card-heading"><h2>Appearance</h2><x-badge>Light</x-badge></div><div class="card-body"><p class="small muted leading-6">A clear light theme is enabled. Additional appearance preferences are not available yet.</p></div></section><section class="card"><div class="card-heading"><h2>System settings</h2><x-badge>Not enabled</x-badge></div><div class="card-body"><p class="small muted leading-6">Organization settings and administrative controls will be introduced with backend role authorization.</p></div></section></div></div></x-layouts.app>
